"""Actual mid-attack direct refresh, independent saved-log replay and ordinary continued win."""
import argparse,asyncio,datetime,json,subprocess
from playwright.async_api import async_playwright
from test_escort_browser import ROOT,KEY,FIELDS,snap,watch,load,begin,complete,Pilot,Driver
async def main(args):
 out=ROOT/args.out;out.parent.mkdir(parents=True,exist_ok=True);errors=[];bad=[];failed=[];report={'testedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'url':args.url,'method':'Fresh120/100HP/2supplies; actual directional dodge and move/combo until active own attack, direct reload during play. Pagehide releases held inputs and saves current tick; independent production replay of actual saved log. No position/HP/energy/supply/time/result writes.'};pilot=await Pilot().start()
 def save():report.update(consoleErrors=errors,badResponses=bad,requestFailures=failed);out.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 async with async_playwright() as pw:
  b=await pw.chromium.launch()
  try:
   ctx=await b.new_context(viewport={'width':1360,'height':1050});p=await ctx.new_page();watch(p,errors,bad,failed);await load(p,args.url);d=await Driver(p).start();await begin(p,d);await d.set({'x':1,'y':1});await d.action('dodge');await p.wait_for_timeout(100);await d.release();before,_,_=await complete(p,pilot,d,stop=lambda s:s['player']['action'] is not None and s['player']['action']['kind']=='attack' and s['ticks']>20);assert before['state']=='playing' and before['player']['action'] and before['stats']['dodges']>=1 and before['player']['spent']>=20;await load(p,args.url,True);saved=await p.evaluate('(k)=>JSON.parse(localStorage.getItem(k)).resume',KEY);after=await snap(p);assert after['state']=='paused';js="import{restore,snapshot}from'./games/escort/engine.mjs';let s='';for await(const x of process.stdin)s+=x;console.log(JSON.stringify(snapshot(restore(JSON.parse(s)))));";expected=json.loads(subprocess.check_output(['node','--input-type=module','-e',js],input=json.dumps(saved),text=True,encoding='utf8',cwd=ROOT));report.update(before=before,savedCheckpoint=saved,restored=after,independentRestored=expected);save();assert all(after[k]==expected[k] for k in FIELDS),[k for k in FIELDS if after[k]!=expected[k]];assert after['controls']=={'x':0,'y':0,'attack':False};await p.wait_for_timeout(250);frozen=await snap(p);assert all(after[k]==frozen[k] for k in FIELDS);await d.release();d=await Driver(p).start();await p.locator('#resume').click();end,_,_=await complete(p,pilot,d);await d.release();assert end['state']=='won' and end['player']['hp']>0 and end['cart']['hp']>0;assert not errors and not bad and not failed,(errors,bad,failed);report.update(passed=True,exactFields=FIELDS,beforeTick=before['ticks'],savedTick=saved['ticks'],continuedWin={k:end[k] for k in ['state','score','ticks','player','cart','heals','stats','log']});save();print(json.dumps({'passed':True,'beforeTick':before['ticks'],'savedTick':saved['ticks'],'exactFields':len(FIELDS),'continuedWin':end['state'],'playerHP':end['player']['hp'],'cartHP':end['cart']['hp']}));await ctx.close()
  except Exception as e:report['error']=type(e).__name__+': '+str(e)[:1800];raise
  finally:save();await b.close();await pilot.close()
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--url',default='https://yydshly.github.io/classic-games-atlas/games/escort/');a.add_argument('--out',default='.local/escort-live-refresh.json');asyncio.run(main(a.parse_args()))
